function validate(input) {
  const [{ Submissions = [] }] = input;
  const parentOf = new Map();
  for (const [id, parent] of Submissions) {
    if (id === null) return 'Every submission needs a sub_id.';
    if (id === parent) return `Submission ${id} replies to itself.`;
    if (parentOf.has(id) && parentOf.get(id) !== parent) return `Submission ${id} has two different parent_id values.`;
    parentOf.set(id, parent);
  }
  return null;
}

