function generate(rand, size) {
  const small = size === 'small';
  const idCount = small ? 12 : 1500;
  // Give every id one role first, so duplicate rows of an id always agree on parent_id.
  const posts = [], roles = [];
  for (let id = 1; id <= idCount; id++) if (rand() < 0.3) posts.push(id);
  for (let id = 1; id <= idCount; id++) {
    if (posts.includes(id)) { roles.push([id, null]); continue; }
    let parent;
    const roll = rand();
    if (roll < 0.75 && posts.length) parent = posts[Math.floor(rand() * posts.length)];
    else if (roll < 0.9) parent = idCount + 1 + Math.floor(rand() * 5); // a post that does not exist
    else parent = 1 + Math.floor(rand() * idCount); // possibly another comment
    if (parent === id) parent = idCount + 1;
    roles.push([id, parent]);
  }
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const Submissions = [];
  for (let i = 0; i < rows; i++) Submissions.push([...roles[Math.floor(rand() * roles.length)]]);
  return [{ Submissions }];
}
